def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for a in my if a == 'D')

    # Endgame exploitation: against a fully cooperative partner, grab value late.
    remaining = 100 - n
    if remaining == 0:
        return 'C'

    if remaining <= 2:
        if opp_d == 0:
            return 'D'
        if opp[-1] == 'D':
            return 'D'
        # If partner is highly cooperative overall, defect on the very last round
        if remaining == 1 and opp_c >= n - 2:
            return 'D'
        return 'C'

    # Detect near-unconditional defection; punish with rare probes.
    if n >= 4 and opp_d >= n - 1:
        if n % 13 == 0:
            return 'C'
        return 'D'

    # Detect near-unconditional cooperation; exploit occasionally.
    if n >= 8 and opp_d == 0:
        if remaining > 12 and n % 9 == 0:
            return 'D'
        return 'C'

    last_opp = opp[-1]

    # If we defected last and opponent still cooperated, resume cooperation.
    if my[-1] == 'D' and last_opp == 'C':
        return 'C'

    # Opponent cooperated: preserve mutual cooperation, with rare probes.
    if last_opp == 'C':
        if n >= 10 and opp_d <= 1 and remaining > 12 and n % 17 == 0:
            return 'D'
        return 'C'

    # Opponent defected. Measure recent behavior for forgiveness/punishment.
    window = opp[-8:] if n >= 8 else opp
    recent_d = sum(1 for a in window if a == 'D')
    wlen = len(window)

    # If defection was rare overall, forgive quickly to restore cooperation.
    if opp_d * 4 <= n and n >= 4:
        if recent_d <= 1:
            return 'C'
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # If we are stuck in mutual defection, offer a conciliatory move.
    if n >= 3 and opp[-2] == 'D' and my[-1] == 'D' and my[-2] == 'D':
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # If opponent defects less than half the time, mix forgiveness and punishment.
    if recent_d * 2 < wlen:
        if rng.random() < 0.45:
            return 'C'
        return 'D'

    # Mostly defecting partner: punish, with occasional probes.
    if rng.random() < 0.08:
        return 'C'
    return 'D'
